// Gemini ka JSON output clean karke parse karo, phir har scene ek alag item banao
const raw = $input.first().json.candidates[0].content.parts[0].text;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);

if (!Array.isArray(parsed.scenes) || parsed.scenes.length === 0) {
  throw new Error('Gemini ne scenes nahi diye. Workflow dobara run karo.');
}

const meta = {
  title: parsed.title,
  description: parsed.description,
  tags: parsed.tags,
};

return parsed.scenes.map((s, i) => ({
  json: {
    scene_index: i + 1,
    hook: s.hook,
    voiceover: s.voiceover,
    pexels_query: s.pexels_query,
    meta,
  },
}));

// Pexels results + scene data ko mila kar JSON2Video ka movie JSON banao
const sceneItems = $('Parse and Split Scenes').all();
const pexelsItems = $('3. Pexels (Free Stock Footage)').all();
const cfg = $('1. Config and API Keys').first().json;
const voice = cfg.VOICE || 'hi-IN-MadhurNeural';
const meta = sceneItems[0].json.meta;

// Pexels response se best portrait video file chuno
function pickFile(videos) {
  if (!Array.isArray(videos) || videos.length === 0) return null;
  for (const v of videos) {
    const files = (v.video_files || [])
      .filter((f) => f.link)
      .sort((a, b) => (b.height || 0) - (a.height || 0));
    const portrait = files.find((f) => f.height > f.width && f.height >= 1280);
    if (portrait) return portrait.link;
  }
  const first = videos[0].video_files && videos[0].video_files[0];
  return first ? first.link : null;
}

const scenes = sceneItems.map((item, i) => {
  const s = item.json;
  const link = pickFile(pexelsItems[i] ? pexelsItems[i].json.videos : null);

  const elements = [];
  // Background footage (nahi mila to text-only scene chalega)
  if (link) elements.push({ type: 'video', src: link });
  // On-screen hook caption
  elements.push({ type: 'text', text: s.hook, position: 'top-center' });
  // Free Hindi/Indian neural voiceover — scene ki duration voice se auto-set hoti hai
  elements.push({ type: 'voice', text: s.voiceover, voice });
  // Auto subtitles, voice ke saath synced
  elements.push({ type: 'subtitles', language: 'hi', settings: { position: 'bottom-center' } });

  const scene = { comment: 'Scene ' + (i + 1), elements };
  if (i > 0) scene.transition = { style: 'fade', duration: 0.5 };
  return scene;
});

const movie = {
  comment: 'Auto-generated by n8n — Free AI YouTube Shorts Generator',
  resolution: 'instagram-story', // 1080x1920 vertical (Shorts)
  quality: 'high',
  scenes,
};

return [{ json: { movie, meta } }];
